"""Module for Marvin client command line interface"""
import argparse
import logging
from typing import Optional

from marvin_client import MarvinClient
from marvin_client.cli.test_control import TestControlCli

# Domain name mapping to CLI handler classes
DOMAIN_TO_CLI_CLASS = {
    "test_ctrl": TestControlCli,
}

# Configure logging. CLI logs to logger "marvin_client.cli".
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(message)s",
)
logging.getLogger("kafka").setLevel("ERROR")

logger = logging.getLogger("marvin_client.cli")


class MarvinClientCli:
    def __init__(self, args: Optional[list[str]] = None) -> None:
        """
        Constructor.
        :param args: Command line arguments. Default `none`, in which case args are taken from the system automatically.
        """
        self._args = args

    def process_command(self) -> None:
        """Process command line arguments"""
        parser = argparse.ArgumentParser("marvin-cli")

        # --env flag
        parser.add_argument(
            "--env",
            metavar="ENVIRONMENT",
            choices=["dev", "prod"],
            help="Environment: 'prod' for Marvin production, 'dev' for Marvin development, default is local",
        )
        # --kafka-servers
        parser.add_argument(
            "--kafka-servers",
            metavar="ADDRESS",
            required=False,
            help="For development only: Kafka bootstrap server addresses separated with comma','",
        )
        # --summary-view-api
        parser.add_argument(
            "--summary-view-api",
            metavar="URL",
            required=False,
            help="For development only: Summary view API URL. E.g. 'http://address:port'",
        )
        # --meta-service-api
        parser.add_argument(
            "--meta-service-api",
            metavar="URL",
            required=False,
            help="For development only: Meta service API URL. E.g. 'http://address:port'",
        )

        # Create sub-parser per domain CLI
        subparsers = parser.add_subparsers(title="Domains", dest="domain", required=True)
        for domain, domain_class in DOMAIN_TO_CLI_CLASS.items():
            domain_parser = subparsers.add_parser(domain)
            domain_class.create_arguments(domain_parser)

        # Parse arguments
        args = parser.parse_args(self._args)

        # Custom post validations in domain CLI classes
        for domain_class in DOMAIN_TO_CLI_CLASS.values():
            domain_class.validate_arguments(parser, args)

        # Forward command to domain CLI object for processing
        marvin_client = MarvinClient(
            environment=args.env,
            kafka_servers=args.kafka_servers,
            summary_view_api=args.summary_view_api,
            meta_service_api=args.meta_service_api,
        )

        domain_cli = DOMAIN_TO_CLI_CLASS[args.domain](args, marvin_client)
        with marvin_client:
            domain_cli.process_command()


def main() -> None:
    """Run CLI. Used as an entry-point for shell command `marvin-client` in CLI packaging. See `pyproject.toml`"""
    cli = MarvinClientCli()

    try:
        cli.process_command()
    except Exception as ex:
        logger.exception("Processing CLI command failed. %s", str(ex))
        exit(1)


if __name__ == "__main__":
    main()
